1	// Offline route resolution: match a request against configured route prefixes
2	// and join the remainder onto the upstream base path without any network I/O.
3	package contractsentinel
4	
5	import (
6		"bytes"
7		"encoding/json"
8		"fmt"
9		"net/netip"
10		"net/url"
11		"sort"
12		"strings"
13	)
14	
15	// Route is one configured route: an id, accepted methods, a path prefix and
16	// the upstream URL requests on that route are forwarded to. An optional
17	// queryTransforms list rewrites the request query string after the route has
18	// been selected.
19	type Route struct {
20		ID              string            `json:"id"`
21		Methods         []string          `json:"methods"`
22		PathPrefix      string            `json:"pathPrefix"`
23		Upstream        string            `json:"upstream"`
24		QueryTransforms []*QueryTransform `json:"-"`
25	
26		// queryTransformsRaw holds the undecoded queryTransforms value until
27		// Config.UnmarshalJSON validates it once the route's position in its own
28		// config is known.
29		queryTransformsRaw json.RawMessage
30	}
31	
32	// QueryTransform is one rule in a route's queryTransforms array: op is
33	// "set", "remove" or "rename"; name is matched against decoded parameter
34	// names, value (set only) is used literally, and to (rename only) is the
35	// literal replacement name.
36	type QueryTransform struct {
37		Op    string `json:"op"`
38		Name  string `json:"name"`
39		Value string `json:"value"`
40		To    string `json:"to"`
41	}
42	
43	// routeJSON mirrors Route but keeps every field raw: the basic fields are
44	// type-checked in Config.UnmarshalJSON with the route's position (and, when
45	// available, its id), so a wrong field type is reported on that route rather
46	// than as a generic JSON decode error, and queryTransforms can surface
47	// null, wrong types and malformed rules the same way.
48	type routeJSON struct {
49		ID              json.RawMessage `json:"id"`
50		Methods         json.RawMessage `json:"methods"`
51		PathPrefix      json.RawMessage `json:"pathPrefix"`
52		Upstream        json.RawMessage `json:"upstream"`
53		QueryTransforms json.RawMessage `json:"queryTransforms"`
54	}
55	
56	// decodeRoute type-checks and decodes one raw route object. loc is the
57	// route's 1-based location in its config (e.g. "route 2"). The element's JSON
58	// type is checked first: a null entry or any non-object value fails on the
59	// entry itself, naming the position, the required object type and the type
60	// actually received, instead of falling through to a missing-field error such
61	// as a missing id. Field type errors then carry that location and, when the
62	// route supplies a valid non-empty string id anywhere in its object (even
63	// after the offending field), that id. Missing fields stay silent here and
64	// are rejected later by validate, which preserves the existing missing-field
65	// behavior.
66	func decodeRoute(data []byte, loc string) (Route, *Failure) {
67		elem := bytes.TrimSpace(data)
68		if len(elem) == 0 || elem[0] != '{' {
69			return Route{}, failuref("invalid_config",
70				"%s: route entry must be an object, got %s", loc, jsonTypeName(elem))
71		}
72		var rj routeJSON
73		if err := json.Unmarshal(elem, &rj); err != nil {
74			// The element already parsed as one JSON value and starts with '{';
75			// an object that cannot be read is a syntax failure rather than a
76			// field type error.
77			return Route{}, failuref("invalid_config", "config is not valid JSON: %v", err)
78		}
79	
80		var route Route
81		// Type-check id first so it can identify the route on an error in any
82		// later field regardless of object order. Only a valid non-empty JSON
83		// string becomes the label; a wrong-typed id is reported against the id
84		// field and never rendered (e.g. as a number or object) as the route's
85		// identity, so that error is located by position alone.
86		if !decodeStringField(rj.ID, &route.ID) {
87			return Route{}, failuref("invalid_config", "%s: id must be a string", loc)
88		}
89		label := loc
90		if route.ID != "" {
91			label = routeLabel(loc, route.ID)
92		}
93	
94		if f := decodeMethodsField(rj.Methods, label, &route.Methods); f != nil {
95			return Route{}, f
96		}
97		if f := decodeRouteStringField(rj.PathPrefix, label, "pathPrefix", &route.PathPrefix); f != nil {
98			return Route{}, f
99		}
100		if f := decodeRouteStringField(rj.Upstream, label, "upstream", &route.Upstream); f != nil {
101			return Route{}, f
102		}
103		route.queryTransformsRaw = rj.QueryTransforms
104		return route, nil
105	}
106	
107	// decodeRouteStringField renders a route field's string type error with the
108	// route's position (and, when available, its id); the type decision itself is
109	// the shared decodeStringField. An absent field stays silent for the later
110	// required-field validation.
111	func decodeRouteStringField(raw json.RawMessage, label, field string, dst *string) *Failure {
112		if !decodeStringField(raw, dst) {
113			return failuref("invalid_config", "%s: %s must be a string", label, field)
114		}
115		return nil
116	}
117	
118	// decodeStringField type-checks a raw field that must hold a string. It is
119	// the one shared string-field decision used by both config and request
120	// decoding, so the absent / null / non-string / empty-string distinctions
121	// live in one place. It returns false only when the key is present with a
122	// non-string value (null included), which is always a field type error. An
123	// absent key leaves dst untouched, and a present string — the empty string
124	// included — is decoded into dst, so both reach the existing content checks
125	// unchanged.
126	func decodeStringField(raw json.RawMessage, dst *string) (isString bool) {
127		if len(raw) == 0 {
128			return true
129		}
130		return jsonString(raw, dst)
131	}
132	
133	// decodeMethodsField type-checks methods: it must be an array of strings
134	// when present. An absent field is left nil for later required-field
135	// validation; null or any non-array value fails the field, and a number,
136	// boolean, object or null entry fails with the offending entry's position.
137	func decodeMethodsField(raw json.RawMessage, label string, dst *[]string) *Failure {
138		if len(raw) == 0 {
139			return nil
140		}
141		body := bytes.TrimSpace(raw)
142		if string(body) == "null" || len(body) == 0 || body[0] != '[' {
143			return failuref("invalid_config", "%s: methods must be an array of strings", label)
144		}
145		var elems []json.RawMessage
146		if err := json.Unmarshal(body, &elems); err != nil {
147			return failuref("invalid_config", "%s: methods must be an array of strings", label)
148		}
149		methods := make([]string, 0, len(elems))
150		for i, elem := range elems {
151			var m string
152			if !jsonString(bytes.TrimSpace(elem), &m) {
153				return failuref("invalid_config", "%s: methods entry %d must be a string", label, i+1)
154			}
155			methods = append(methods, m)
156		}
157		*dst = methods
158		return nil
159	}
160	
161	// parseQueryTransforms decodes and validates the raw queryTransforms array
162	// of one route. loc identifies the route; rule errors additionally carry a
163	// 1-based rule index.
164	func parseQueryTransforms(raw json.RawMessage, loc, id string) ([]*QueryTransform, *Failure) {
165		body := strings.TrimSpace(string(raw))
166		if body == "null" {
167			return nil, failuref("invalid_config", "%s: queryTransforms must not be null", routeLabel(loc, id))
168		}
169		var elems []json.RawMessage
170		if err := json.Unmarshal([]byte(body), &elems); err != nil {
171			return nil, failuref("invalid_config", "%s: queryTransforms must be an array", routeLabel(loc, id))
172		}
173		transforms := make([]*QueryTransform, 0, len(elems))
174		for i, elem := range elems {
175			ruleLoc := fmt.Sprintf("%s, queryTransforms rule %d", routeLabel(loc, id), i+1)
176			if string(bytes.TrimSpace(elem)) == "null" {
177				return nil, failuref("invalid_config", "%s: rule must not be null", ruleLoc)
178			}
179			var fields map[string]json.RawMessage
180			if err := json.Unmarshal(elem, &fields); err != nil {
181				return nil, failuref("invalid_config", "%s: rule must be a JSON object", ruleLoc)
182			}
183	
184			qt := &QueryTransform{}
185			opRaw, ok := fields["op"]
186			switch {
187			case !ok:
188				return nil, failuref("invalid_config", "%s: op is required", ruleLoc)
189			case !jsonString(opRaw, &qt.Op):
190				return nil, failuref("invalid_config", "%s: op must be a string", ruleLoc)
191			case qt.Op != "set" && qt.Op != "remove" && qt.Op != "rename":
192				return nil, failuref("invalid_config", "%s: unknown op %q (only set, remove and rename are supported)", ruleLoc, qt.Op)
193			}
194	
195			nameRaw, ok := fields["name"]
196			switch {
197			case !ok:
198				return nil, failuref("invalid_config", "%s: name is required", ruleLoc)
199			case !jsonString(nameRaw, &qt.Name):
200				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
201			case qt.Name == "":
202				return nil, failuref("invalid_config", "%s: name must be a non-empty string", ruleLoc)
203			}
204	
205			valueRaw, hasValue := fields["value"]
206			toRaw, hasTo := fields["to"]
207			switch qt.Op {
208			case "set":
209				if !hasValue {
210					return nil, failuref("invalid_config", "%s: set requires a string value", ruleLoc)
211				}
212				if !jsonString(valueRaw, &qt.Value) {
213					return nil, failuref("invalid_config", "%s: value must be a string", ruleLoc)
214				}
215			case "remove":
216				if hasValue {
217					return nil, failuref("invalid_config", "%s: remove must not include a value", ruleLoc)
218				}
219			case "rename":
220				if hasValue {
221					return nil, failuref("invalid_config", "%s: rename must not include a value", ruleLoc)
222				}
223				switch {
224				case !hasTo:
225					return nil, failuref("invalid_config", "%s: rename requires a non-empty string to", ruleLoc)
226				case !jsonString(toRaw, &qt.To):
227					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
228				case qt.To == "":
229					return nil, failuref("invalid_config", "%s: to must be a non-empty string", ruleLoc)
230				}
231			}
232			transforms = append(transforms, qt)
233		}
234		return transforms, nil
235	}
236	
237	// jsonString decodes raw into s and reports whether raw is a JSON string
238	// (null, numbers, objects and arrays fail).
239	func jsonString(raw json.RawMessage, s *string) bool {
240		if len(raw) == 0 || raw[0] != '"' {
241			return false
242		}
243		return json.Unmarshal(raw, s) == nil
244	}
245	
246	// routeLabel renders the human-readable route location, adding the id when
247	// the configuration supplied one.
248	func routeLabel(loc, id string) string {
249		if id != "" {
250			return fmt.Sprintf("%s (id %q)", loc, id)
251		}
252		return loc
253	}
254	
255	// Config is the resolve configuration: a flat array of routes.
256	type Config struct {
257		Routes []Route `json:"routes"`
258	}
259	
260	// UnmarshalJSON first confirms the document is one syntactically valid JSON
261	// value, then checks its structure: the top-level value must be a JSON object
262	// and, when present, the routes field must hold an array. A syntactically
263	// legal value of the wrong shape (an array, string, number, boolean or null
264	// at the top level; a non-array routes, null included) is an invalid_config
265	// naming both the required type and the type received, never a JSON parse
266	// failure. The routes array is then decoded one entry at a time, each entry
267	// type-checked and validated against its 1-based position in this config; a
268	// non-object entry (null included) fails on that entry before any field is
269	// inspected. Decoding entries from raw values means wrong field types are
270	// reported on the offending route (with its id when available) instead of
271	// as a generic JSON syntax failure. The position comes from the array
272	// decoded here, so configs parsed concurrently or interleaved in the same
273	// process cannot shift each other's route numbering. A broken JSON document
274	// still fails the outer decode and is reported as a parse failure, without a
275	// guessed route position or field.
276	func (cfg *Config) UnmarshalJSON(data []byte) error {
277		// Syntax first, then the top-level shape; both basic checks are shared
278		// with ParseRequest (see unmarshalJSONValue / requireJSONObject), only
279		// the code and wording differ.
280		body, err := unmarshalJSONValue(data)
281		if err != nil {
282			return err
283		}
284		if f := requireJSONObject(body, "invalid_config", "config", true); f != nil {
285			return f
286		}
287		var fields map[string]json.RawMessage
288		if err := json.Unmarshal(body, &fields); err != nil {
289			return err
290		}
291	
292		var rawRoutes []json.RawMessage
293		if raw, ok := fields["routes"]; ok {
294			body := bytes.TrimSpace(raw)
295			if len(body) == 0 || body[0] != '[' {
296				// null is a type error here, never an absent field: a config
297				// that explicitly supplies routes must supply an array.
298				return failuref("invalid_config", "routes must be an array, got %s", jsonTypeName(body))
299			}
300			if err := json.Unmarshal(body, &rawRoutes); err != nil {
301				return err
302			}
303		}
304	
305		// Pass 1: decode and type-check every entry, so a wrong field type on a
306		// later route fails before any queryTransforms validation (matching the
307		// precedence of decoding before validation).
308		cfg.Routes = make([]Route, len(rawRoutes))
309		for i, entry := range rawRoutes {
310			route, f := decodeRoute(entry, fmt.Sprintf("route %d", i+1))
311			if f != nil {
312				return f
313			}
314			cfg.Routes[i] = route
315		}
316		// Pass 2: validate each route's queryTransforms now that every position
317		// is known.
318		for i := range cfg.Routes {
319			route := &cfg.Routes[i]
320			if len(route.queryTransformsRaw) == 0 {
321				continue // field absent
322			}
323			loc := fmt.Sprintf("route %d", i+1)
324			transforms, f := parseQueryTransforms(route.queryTransformsRaw, loc, route.ID)
325			if f != nil {
326				return f
327			}
328			route.QueryTransforms = transforms
329			route.queryTransformsRaw = nil
330		}
331		return nil
332	}
333	
334	// unmarshalJSONValue is the shared first step of parsing either input: it
335	// confirms the document is one syntactically valid JSON value, without
336	// judging its shape. It returns encoding/json's own error verbatim, so each
337	// caller keeps its existing handling (ParseConfig wraps a returned error just
338	// as Config.UnmarshalJSON returning it directly always has).
339	func unmarshalJSONValue(data []byte) (json.RawMessage, error) {
340		var doc json.RawMessage
341		if err := json.Unmarshal(data, &doc); err != nil {
342			return nil, err
343		}
344		return bytes.TrimSpace(doc), nil
345	}
346	
347	// requireJSONObject is the shared top-level shape check: a syntactically
348	// legal value that is not a JSON object is a structural error in the caller's
349	// code saying "<what> must be a JSON object", never a parse failure and never
350	// a guessed field or route position. Config errors additionally name the type
351	// actually received ("got <type>"); the request wording omits it.
352	func requireJSONObject(doc json.RawMessage, code, what string, nameType bool) *Failure {
353		if len(doc) == 0 || doc[0] != '{' {
354			if nameType {
355				return failuref(code, "%s must be a JSON object, got %s", what, jsonTypeName(doc))
356			}
357			return failuref(code, "%s must be a JSON object", what)
358		}
359		return nil
360	}
