375	// Failure carries a stable machine-readable code and a human-readable reason.
376	type Failure struct {
377		Code       string   `json:"code"`
378		Reason     string   `json:"reason"`
379		Candidates []string `json:"candidates,omitempty"`
380	}
381	
382	func (f *Failure) Error() string { return f.Code + ": " + f.Reason }
383	
384	func failuref(code, format string, args ...any) *Failure {
385		return &Failure{Code: code, Reason: fmt.Sprintf(format, args...)}
386	}
