388	// ParseConfig parses and fully validates the route configuration.
389	func ParseConfig(data []byte) (*Config, *Failure) {
390		var cfg Config
391		if err := json.Unmarshal(data, &cfg); err != nil {
392			if f, ok := err.(*Failure); ok {
393				return nil, f
394			}
395			return nil, failuref("invalid_config", "config is not valid JSON: %v", err)
396		}
397		if f := cfg.validate(); f != nil {
398			return nil, f
399		}
400		return &cfg, nil
401	}
402	
403	func (cfg *Config) validate() *Failure {
404		seenIDs := make(map[string]int, len(cfg.Routes))
405		for i := range cfg.Routes {
406			route := &cfg.Routes[i]
407			loc := fmt.Sprintf("route %d", i+1)
408			if route.ID == "" {
409				return failuref("invalid_config", "%s: id must be non-empty", loc)
410			}
411			if first, ok := seenIDs[route.ID]; ok {
412				return failuref("invalid_config", "%s: duplicate id %q (already used by route %d)", loc, route.ID, first)
413			}
414			seenIDs[route.ID] = i + 1
415	
416			if len(route.Methods) == 0 {
417				return failuref("invalid_config", "%s (id %q): methods must be a non-empty array", loc, route.ID)
418			}
419			for _, method := range route.Methods {
420				switch {
421				case method == "":
422					return failuref("invalid_config", "%s (id %q): methods must not contain empty entries", loc, route.ID)
423				case method == "*":
424					// Wildcard matching any legal method.
425				case !isToken(method):
426					return failuref("invalid_config", "%s (id %q): invalid method %q", loc, route.ID, method)
427				}
428			}
429	
430			if f := validatePrefix(route.PathPrefix, loc, route.ID); f != nil {
431				return f
432			}
433			if f := validateUpstream(route.Upstream, loc, route.ID); f != nil {
434				return f
435			}
436		}
437		return nil
438	}
439	
440	func validatePrefix(prefix, loc, id string) *Failure {
441		switch {
442		case prefix == "" || prefix[0] != '/':
443			return failuref("invalid_config", "%s (id %q): pathPrefix must start with /", loc, id)
444		case prefix != "/" && strings.HasSuffix(prefix, "/"):
445			return failuref("invalid_config", "%s (id %q): pathPrefix must not end with / except for root", loc, id)
446		case strings.ContainsAny(prefix, "?#"):
447			return failuref("invalid_config", "%s (id %q): pathPrefix must not contain a query string or fragment", loc, id)
448		case !validPercentEscapes(prefix):
449			return failuref("invalid_config", "%s (id %q): pathPrefix contains an invalid percent escape", loc, id)
450		}
451		return nil
452	}
453	
454	func validateUpstream(raw, loc, id string) *Failure {
455		if strings.ContainsAny(raw, "?#") {
456			return failuref("invalid_config", "%s (id %q): upstream must not contain a query string or fragment", loc, id)
457		}
458		// Validate any bracketed host against the raw string before url.Parse:
459		// square brackets are the IP-literal marker, so whatever they enclose
460		// must be a legal IPv6 address (zone included) rather than a name or an
461		// IPv4 address. Doing this explicitly keeps the rule independent of
462		// url.Parse's parser strictness and lets the reason name the field and
463		// the actual problem instead of surfacing a generic URL parse error.
464		if f := validateBracketedUpstreamHost(raw, loc, id); f != nil {
465			return f
466		}
467		u, err := url.Parse(raw)
468		if err != nil {
469			return failuref("invalid_config", "%s (id %q): upstream is not a valid URL: %v", loc, id, err)
470		}
471		if u.Scheme != "http" && u.Scheme != "https" {
472			return failuref("invalid_config", "%s (id %q): upstream must be an absolute http or https URL", loc, id)
473		}
474		if u.Host == "" {
475			return failuref("invalid_config", "%s (id %q): upstream must include a host", loc, id)
476		}
477		return nil
478	}
479	
480	// validateBracketedUpstreamHost checks the raw upstream's authority for an
481	// IP literal in square brackets: brackets are reserved for an IPv6 (or
482	// future IP-version) literal, so their content must parse as an IPv6 address
483	// — full form, compressed form or an IPv6 address with an embedded IPv4
484	// tail — and the brackets must wrap the whole host exactly once:
485	//
486	//	"[" IPv6 "]" [ ":" *DIGIT ]
487	//
488	// A port, userinfo and a percent-encoded zone ("%25eth0") are allowed and
489	// never alter the literal's bytes; an empty pair of brackets, a plain
490	// hostname such as "[not-an-ip]", a bare IPv4 address such as
491	// "[127.0.0.1]", a malformed IPv6 literal, a missing closing bracket, a
492	// second bracket group such as "[::1][::2]", a stray closing bracket or any
493	// other text between the closing bracket and the start of the base path
494	// (including junk around the port such as "[::1]:80a" or "[::1]x]:80") are
495	// rejected — a legal first literal never legitimizes trailing content. The
496	// reason names the route, its id and the upstream field. This is a content
497	// error in a syntactically valid JSON document, never a JSON parse failure,
498	// and the rule is enforced here on the raw bytes rather than left to
499	// url.Parse's parser strictness.
500	func validateBracketedUpstreamHost(raw, loc, id string) *Failure {
501		// The authority starts after the scheme separator and ends at the first
502		// path slash (query and fragment were rejected by the caller).
503		schemeEnd := strings.Index(raw, "://")
504		if schemeEnd < 0 {
505			return nil // no scheme: the generic absolute-URL check reports this
506		}
507		authority := raw[schemeEnd+3:]
508		if i := strings.IndexByte(authority, '/'); i >= 0 {
509			authority = authority[:i]
510		}
511		// Any userinfo precedes the host and ends at the last '@'.
512		hostPort := authority
513		if i := strings.LastIndexByte(authority, '@'); i >= 0 {
514			hostPort = authority[i+1:]
515		}
516	
517		if !strings.ContainsAny(hostPort, "[]") {
518			return nil // ordinary reg-name (domain) or bare IPv4 host stays as-is
519		}
520		label := routeLabel(loc, id)
521		if !strings.HasPrefix(hostPort, "[") {
522			return failuref("invalid_config",
523				"%s: upstream bracketed host must be a single '[' IPv6 address ']' pair: '[' may only open the host", label)
524		}
525		closeBracket := strings.IndexByte(hostPort, ']')
526		if closeBracket < 0 {
527			return failuref("invalid_config",
528				"%s: upstream bracketed host must be a valid IPv6 address but the closing ']' is missing", label)
529		}
530		literal := hostPort[1:closeBracket]
531		// The zone delimiter is percent-encoded in the URL ("%25"); decode the
532		// literal's escapes once so netip sees "fe80::1%eth0" while every other
533		// byte keeps its original spelling.
534		decoded, err := url.PathUnescape(literal)
535		if err != nil {
536			return invalidBracketedHost(label, literal)
537		}
538		addr, err := netip.ParseAddr(decoded)
539		if err != nil || !addr.Is6() {
540			// ParseAddr accepts a bare IPv4 address; brackets may only carry
541			// IPv6, so "[127.0.0.1]" is rejected even though it is a valid IP.
542			return invalidBracketedHost(label, literal)
543		}
544		// The one closing bracket ends the host: the rest of the authority may
545		// be empty or the optional port the generic parser already allows
546		// (":" followed by digits, an empty port included). A repeated bracket
547		// group, a stray ']', or any other text before, beside or after a port
548		// fails here even though the first literal was valid — the brackets
549		// must enclose the whole host exactly once.
550		suffix := hostPort[closeBracket+1:]
551		switch {
552		case suffix == "":
553			return nil
554		case strings.ContainsAny(suffix, "[]"):
555			return invalidBracketedHostShape(label, suffix)
556		case suffix[0] != ':':
557			return invalidBracketedHostShape(label, suffix)
558		}
559		port := suffix[1:]
560		for i := 0; i < len(port); i++ {
561			if port[i] < '0' || port[i] > '9' {
562				return invalidBracketedHostShape(label, suffix)
563			}
564		}
565		return nil
566	}
567	
568	// invalidBracketedHost builds the content error for a bracketed host whose
569	// content is not a legal IPv6 literal.
570	func invalidBracketedHost(label, literal string) *Failure {
571		return failuref("invalid_config",
572			"%s: upstream host in brackets must be a valid IPv6 address, but %q is not a legal IPv6 address", label, literal)
573	}
574	
575	// invalidBracketedHostShape builds the content error for a bracketed host
576	// whose trailing bytes break the "single '[' IPv6 ']' pair plus optional
577	// port" grammar, e.g. a repeated bracket group, a stray closing bracket or
578	// non-port text after the closing bracket.
579	func invalidBracketedHostShape(label, suffix string) *Failure {
580		return failuref("invalid_config",
581			"%s: upstream bracketed host must be a single '[' IPv6 address ']' pair followed only by an optional port, but %q follows the closing ']'", label, suffix)
582	}
583	
584	// requestJSON mirrors Request but keeps method and target raw, so a valid
585	// JSON document whose fields merely have the wrong JSON type is reported on
586	// the offending field instead of as a generic JSON decode error.
587	type requestJSON struct {
588		Method json.RawMessage `json:"method"`
589		Target json.RawMessage `json:"target"`
590	}
591	
592	// ParseRequest parses and validates one JSON request. Three failure shapes are
593	// kept apart: a document whose JSON syntax is broken fails as a parse failure
594	// without guessing a field; a syntactically valid non-object document (array,
595	// number, string, boolean or null) must be a JSON object; a valid object whose
596	// method or target is not a string fails on that field, naming the JSON type
597	// actually received (null counts as a type error, never as a missing field).
598	// method is always checked before target, regardless of the key order in the
599	// object. Only after both fields are present strings are their contents
600	// (required method, legal token, absolute target without a fragment or a bad
601	// percent escape) validated, so an empty string stays a content error.
602	func ParseRequest(data []byte) (*Request, *Failure) {
603		body, err := unmarshalJSONValue(data)
604		if err != nil {
605			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
606		}
607		if f := requireJSONObject(body, "invalid_request", "request", false); f != nil {
608			return nil, f
609		}
610	
611		var rj requestJSON
612		if err := json.Unmarshal(body, &rj); err != nil {
613			// The document already parsed as one JSON value and starts with '{';
614			// keep this as a parse failure rather than a field error if the object
615			// itself cannot be read.
616			return nil, failuref("invalid_request", "request is not valid JSON: %v", err)
617		}
618	
619		var req Request
620		// method is always checked before target, regardless of the key order in
621		// the object; the absent/null/non-string distinction is the shared
622		// decodeStringField, so only the request wording is added here.
623		if f := decodeRequestStringField(rj.Method, "method", &req.Method); f != nil {
624			return nil, f
625		}
626		if f := decodeRequestStringField(rj.Target, "target", &req.Target); f != nil {
627			return nil, f
628		}
629	
630		switch {
631		case req.Method == "":
632			return nil, failuref("invalid_request", "method is required")
633		case !isToken(req.Method):
634			return nil, failuref("invalid_request", "method %q is not a legal HTTP method", req.Method)
635		}
636		switch {
637		case req.Target == "" || req.Target[0] != '/':
638			return nil, failuref("invalid_request", "target must start with /")
639		case strings.Contains(req.Target, "#"):
640			return nil, failuref("invalid_request", "target must not contain a fragment")
641		case !validPercentEscapes(req.Target):
642			return nil, failuref("invalid_request", "target contains an invalid percent escape")
643		}
644		return &req, nil
645	}
646	
647	// decodeRequestStringField renders the request wording for one string field;
648	// the absent/null/non-string decision itself is the shared
649	// decodeStringField. An absent field (no such key) is left as the zero value
650	// so the later content checks keep their "field is required" behavior; null
651	// or any non-string JSON value is a type error that names the field and the
652	// JSON type that was actually supplied.
653	func decodeRequestStringField(raw json.RawMessage, field string, dst *string) *Failure {
654		if !decodeStringField(raw, dst) {
655			return failuref("invalid_request", "%s must be a string, got %s", field, jsonTypeName(raw))
656		}
657		return nil
658	}
659	
660	// jsonTypeName names the JSON type of a syntactically valid raw value, in the
661	// terms the request error reasons use: "null", "a boolean", "a number",
662	// "a string", "an array" or "an object".
663	func jsonTypeName(raw json.RawMessage) string {
664		switch bytes.TrimSpace(raw)[0] {
665		case 'n':
666			return "null"
667		case 't', 'f':
668			return "a boolean"
669		case '"':
670			return "a string"
671		case '[':
672			return "an array"
673		case '{':
674			return "an object"
675		default:
676			return "a number"
677		}
678	}
679	
680	// Resolve matches a validated request against a validated configuration and
681	// computes the upstream URL. Failure codes are route_not_found and
682	// route_conflict.
683	func Resolve(cfg *Config, req *Request) (*Resolution, *Failure) {
684		path := req.Target
685		if i := strings.IndexByte(path, '?'); i >= 0 {
686			path = path[:i]
687		}
688	
689		type candidate struct {
690			route    *Route
691			concrete bool
692		}
693		var matched []candidate
694		for i := range cfg.Routes {
695			route := &cfg.Routes[i]
696			concrete, wildcard := methodMatch(route.Methods, req.Method)
697			if !concrete && !wildcard {
698				continue
699			}
700			if !prefixMatch(route.PathPrefix, path) {
701				continue
702			}
703			matched = append(matched, candidate{route, concrete})
704		}
705		if len(matched) == 0 {
706			return nil, failuref("route_not_found", "no route matches %s %s", req.Method, path)
707		}
708	
709		// Longest prefix wins.
710		bestLen := 0
711		for _, c := range matched {
712			if n := len(c.route.PathPrefix); n > bestLen {
713				bestLen = n
714			}
715		}
716		winners := matched[:0]
717		for _, c := range matched {
718			if len(c.route.PathPrefix) == bestLen {
719				winners = append(winners, c)
720			}
721		}
722	
723		// Among equal prefixes a concrete method beats the wildcard.
724		var concrete []candidate
725		for _, c := range winners {
726			if c.concrete {
727				concrete = append(concrete, c)
728			}
729		}
730		if len(concrete) > 0 {
731			winners = concrete
732		}
733		if len(winners) > 1 {
734			ids := make([]string, 0, len(winners))
735			for _, c := range winners {
736				ids = append(ids, c.route.ID)
737			}
738			sort.Strings(ids)
739			f := failuref("route_conflict", "multiple routes match %s %s", req.Method, path)
740			f.Candidates = ids
741			return nil, f
742		}
743	
744		upstreamURL, f := joinUpstream(winners[0].route, path, req.Target)
745		if f != nil {
746			return nil, f
747		}
748		return &Resolution{RouteID: winners[0].route.ID, UpstreamURL: upstreamURL}, nil
749	}
750	
751	// methodMatch reports whether the method list matches the request method
752	// concretely (an exact, case-sensitive entry) or via the "*" wildcard.
753	func methodMatch(methods []string, method string) (concrete, wildcard bool) {
754		for _, m := range methods {
755			switch {
756			case m == "*":
757				wildcard = true
758			case m == method:
759				concrete = true
760			}
761		}
762		return concrete, wildcard
763	}
764	
765	// prefixMatch matches raw encoded paths on segment boundaries: "%2F" is never
766	// treated as a separator and the root prefix matches every origin-path.
767	func prefixMatch(prefix, path string) bool {
768		if prefix == "/" {
769			return true
770		}
771		if path == prefix {
772			return true
773		}
774		return strings.HasPrefix(path, prefix) && path[len(prefix)] == '/'
775	}
776	
777	// joinUpstream strips the route prefix from the request path and joins the
778	// remainder onto the upstream base path with exactly one slash at the
779	// junction. The junction is one run of literal slashes: every trailing
780	// slash on the base path and every leading slash on the remainder are
781	// merged into that single slash, even when either side contributes
782	// several. Nothing else is normalized: slashes inside either part, the
783	// remainder's trailing slashes (once non-slash content has appeared),
784	// ".", ".." and percent escapes such as "%2F" are carried over byte for
785	// byte, never decoded first. The base path is sliced out of the raw
786	// upstream so joining never re-encodes, reorders or drops anything
787	// outside the junction. The raw query is preserved verbatim unless the
788	// route defines queryTransforms, in which case they rewrite it after
789	// route selection.
790	func joinUpstream(route *Route, path, target string) (string, *Failure) {
791		if _, err := url.Parse(route.Upstream); err != nil {
792			// Config validation already rejected this.
793			return "", failuref("invalid_config", "route %q has an invalid upstream: %v", route.ID, err)
794		}
795	
796		var remainder string
797		switch {
798		case route.PathPrefix == "/":
799			// Root keeps the whole following path; "/" itself has an empty remainder.
800			if path != "/" {
801				remainder = path
802			}
803		default:
804			remainder = path[len(route.PathPrefix):] // "" or "/...", boundary is a literal slash
805		}
806	
807		// Slice the validated upstream raw so nothing outside the junction is
808		// normalized or re-escaped (scheme://[userinfo@]host[/base-path]).
809		schemeEnd := strings.Index(route.Upstream, "://")
810		tail := route.Upstream[schemeEnd+3:]
811		hostPart, basePath := tail, ""
812		if i := strings.IndexByte(tail, '/'); i >= 0 {
813			hostPart, basePath = tail[:i], tail[i:]
814		}
815	
816		// Collapse only the junction run: all trailing slashes of the base
817		// path meet all leading slashes of the remainder, and the junction
818		// keeps exactly one slash whether or not anything follows them. A
819		// remainder made entirely of slashes has no content past the run, so
820		// it likewise ends in that single slash.
821		baseTrimmed := strings.TrimRight(basePath, "/")
822		rest := strings.TrimLeft(remainder, "/")
823		joined := baseTrimmed + "/" + rest
824	
825		result := route.Upstream[:schemeEnd+3] + hostPart + joined
826		query, f := applyQueryTransforms(route.QueryTransforms, target)
827		if f != nil {
828			return "", f
829		}
830		return result + query, nil
831	}
832	
833	// isToken reports whether s is an RFC 7230 token, i.e. a legal HTTP method.
834	func isToken(s string) bool {
835		if s == "" {
836			return false
837		}
838		for i := 0; i < len(s); i++ {
839			if !isTokenChar(s[i]) {
840				return false
841			}
842		}
843		return true
844	}
845	
846	func isTokenChar(c byte) bool {
847		switch {
848		case c >= 'a' && c <= 'z', c >= 'A' && c <= 'Z', c >= '0' && c <= '9':
849			return true
850		}
851		switch c {
852		case '!', '#', '$', '%', '&', '\'', '*', '+', '-', '.', '^', '_', '`', '|', '~':
853			return true
854		}
855		return false
856	}
857	
858	// validPercentEscapes checks that every "%' is followed by two hex digits.
859	// Matching and joining stay on raw strings, but malformed escapes are rejected
860	// up front for both prefixes and request targets.
861	func validPercentEscapes(s string) bool {
862		for i := 0; i < len(s); i++ {
863			if s[i] != '%' {
864				continue
865			}
866			if i+2 >= len(s) || !isHex(s[i+1]) || !isHex(s[i+2]) {
867				return false
868			}
869			i += 2
870		}
871		return true
872	}
873	
874	func isHex(c byte) bool {
875		switch {
876		case c >= '0' && c <= '9', c >= 'a' && c <= 'f', c >= 'A' && c <= 'F':
877			return true
878		}
879		return false
880	}
881

