package contractsentinel

import (
	"encoding/json"
	"strings"
	"testing"
)

func TestScratchRoundTrip(t *testing.T) {
	// Rule names/values deliberately hold spaces, Chinese, '+' and raw '%'.
	src := `{"routes":[
	  {"id":"no-rules","methods":["get"],"pathPrefix":"/a","upstream":"http://h1.example/base"},
	  {"id":"empty","methods":["*"],"pathPrefix":"/b","upstream":"https://h2.example/x","queryTransforms":[]},
	  {"id":"rich","methods":["GET","POST"],"pathPrefix":"/c","upstream":"http://h3.example/u",
	   "queryTransforms":[
	     {"op":"rename","name":"a+b","to":"中 文+"},
	     {"op":"rename","name":"%","to":"zz"},
	     {"op":"set","name":"dup","value":""},
	     {"op":"set","name":"new","value":"a b+c%20d"},
	     {"op":"remove","name":"flag"}
	   ]}
	]}`
	cfg, f := ParseConfig([]byte(src))
	if f != nil {
		t.Fatalf("parse: %v", f)
	}
	out, err := json.Marshal(cfg)
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("saved: %s", out)

	// Literal strings survive: no query encoding/decoding on save.
	if !strings.Contains(string(out), `"name":"a+b"`) ||
		!strings.Contains(string(out), `"to":"中 文+"`) ||
		!strings.Contains(string(out), `"name":"%"`) ||
		!strings.Contains(string(out), `"value":"a b+c%20d"`) {
		t.Fatalf("special chars not literal: %s", out)
	}
	// Per-op field shape.
	if strings.Contains(string(out), `"value":""},"op":"remove"`) {
		t.Fatal("remove carried a value")
	}
	var probe []struct {
		Op    string  `json:"op"`
		Name  string  `json:"name"`
		Value *string `json:"value"`
		To    *string `json:"to"`
	}
	if err := json.Unmarshal([]byte(extractRichArray(t, out)), &probe); err != nil {
		t.Fatal(err)
	}
	for _, r := range probe {
		switch r.Op {
		case "set":
			if r.Value == nil || r.To != nil {
				t.Fatalf("set shape wrong: %+v", r)
			}
		case "remove":
			if r.Value != nil || r.To != nil {
				t.Fatalf("remove shape wrong: %+v", r)
			}
		case "rename":
			if r.Value != nil || r.To == nil || *r.To == "" {
				t.Fatalf("rename shape wrong: %+v", r)
			}
		}
	}

	// null must never appear for routes/queryTransforms.
	if strings.Contains(string(out), `null`) {
		t.Fatalf("output contains null: %s", out)
	}

	cfg2, f := ParseConfig(out)
	if f != nil {
		t.Fatalf("re-parse: %v", f)
	}
	cases := []string{
		"/a/1?keep=1&keep=2&x=",
		"/b?%41=1&A=2",
		"/c?a+b=1&a%2Bb=2&%25=q&dup=1&dup=2&flag&untouched=中%20x&new=old",
